// CLIENT-ONLY PREFERENCE -> localStorage (not sent to server)
function saveTheme(theme) {
  localStorage.setItem('prefs', JSON.stringify({ theme }));
}
function loadTheme() {
  const raw = localStorage.getItem('prefs');
  return raw ? JSON.parse(raw).theme : 'light';
}
saveTheme('dark');
console.log(loadTheme()); // 'dark' (survives reload & restart)

